const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) {
  staticData.contentHistory = [];
}

const history = staticData.contentHistory.slice(-80);

const previous = history.length
  ? history.map((x, i) => `${i + 1}. TITLE: ${x.title}\nHOOK: ${x.hook}\nTOPIC: ${x.topic}`).join('\n')
  : 'No previous content exists yet.';

const system = `You are a viral YouTube Shorts scriptwriter specialising in surprising, verifiable "Did you know?" facts.

Return ONLY a single JSON object, no markdown, with EXACTLY these keys:

hook - a 1-sentence pattern-interrupt opener and the first line of the script.
script - FULL narration to be spoken. Start with the hook. 90-130 words. Conversational and punchy. ONE genuinely surprising verified fact. End with a short question or follow-for-more style line. No emojis, hashtags or stage directions.
title - <= 90 characters and MUST end with " #Shorts".
description - 2-3 sentences, then a new line with 5 relevant hashtags.
tags - array of 8-12 lowercase keyword strings.
query - 1-2 word stock-video search term matching the visual mood.
voice - exactly one of: en-US-AriaNeural, en-US-GuyNeural, en-GB-SoniaNeural.
topic - a short description of the core fact/topic.

IMPORTANT CONTENT DIVERSITY RULES:
- Vary topics across science, space, history, biology, psychology, technology and nature.
- Do NOT reuse any previous topic.
- Do NOT make a different version of a previous fact.
- Do NOT reuse the same hook structure repeatedly.
- Do NOT reuse a previous title or nearly identical title.
- Choose a completely different fact if anything below is similar.
- Prefer facts that genuinely make viewers think: wait, what?!

PREVIOUS CONTENT TO AVOID:
${previous}`;

const body = {
  model: 'llama-3.3-70b-versatile',
  temperature: 1.05,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    {
      role: 'user',
      content: 'Generate ONE completely fresh Short that is substantially different from every previous item listed above. Respond with the JSON object only.'
    }
  ]
};

return [{ json: { body } }];

const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message.content;

if (!content) {
  throw new Error('No content from Groq: ' + JSON.stringify(res).slice(0, 800));
}

let data;
try {
  data = JSON.parse(content);
} catch (e) {
  throw new Error('Groq did not return valid JSON: ' + content.slice(0, 800));
}

if (!data.script || !data.title || !data.hook) {
  throw new Error('Groq JSON missing script/title/hook');
}

data.tags = Array.isArray(data.tags) ? data.tags : [];
data.voice = data.voice || 'en-US-AriaNeural';
data.query = data.query || 'abstract';
data.topic = data.topic || data.title;

if (!data.title.toLowerCase().includes('#shorts')) {
  data.title = data.title.replace(/\s*$/,'') + ' #Shorts';
}

return [{ json: data }];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) {
  staticData.contentHistory = [];
}

const history = staticData.contentHistory;

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/#shorts/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function words(text) {
  return new Set(
    normalize(text)
      .split(' ')
      .filter(w => w.length > 3)
  );
}

function similarity(a, b) {
  const A = words(a);
  const B = words(b);
  if (!A.size || !B.size) return 0;
  let intersection = 0;
  for (const w of A) {
    if (B.has(w)) intersection++;
  }
  return intersection / Math.max(1, Math.min(A.size, B.size));
}

const candidateText = [
  item.title,
  item.hook,
  item.topic,
  item.script
].join(' ');

let duplicate = false;
let reason = '';

for (const old of history.slice(-80)) {
  if (normalize(item.title) === normalize(old.title)) {
    duplicate = true;
    reason = 'duplicate title';
    break;
  }

  if (normalize(item.hook) === normalize(old.hook)) {
    duplicate = true;
    reason = 'duplicate hook';
    break;
  }

  if (similarity(item.topic, old.topic) >= 0.60) {
    duplicate = true;
    reason = 'very similar topic';
    break;
  }

  if (similarity(candidateText, [old.title, old.hook, old.topic, old.script].join(' ')) >= 0.58) {
    duplicate = true;
    reason = 'very similar content';
    break;
  }
}

if (duplicate) {
  throw new Error('DUPLICATE_CONTENT_REJECTED: ' + reason + '. Generate a different fact/topic.');
}

history.push({
  title: item.title,
  hook: item.hook,
  topic: item.topic,
  script: item.script,
  query: item.query,
  createdAt: new Date().toISOString()
});

while (history.length > 80) history.shift();

return [{ json: item }];

const item = $input.first().json;
const runId = String($execution.id || Date.now());
const runDir = `/data/${runId}`;
const job = {
  script: item.script,
  query: item.query,
  voice: item.voice
};
const jobB64 = Buffer.from(JSON.stringify(job), 'utf8').toString('base64');

return [{ json: {
  runId,
  runDir,
  jobB64,
  title: item.title,
  description: item.description,
  tags: item.tags,
  topic: item.topic
} }];
